// Aggregate and deduplicate news from all RSS feeds
// Filter for items published in the last 4 hours
const allItems = $input.all();
const fourHoursAgo = Date.now() - (4 * 60 * 60 * 1000);

const keywords = [
  'berkshire', 'buffett', 'munger', 'daily journal',
  'market crash', 'bubble', 'recession', 'inflation',
  'federal reserve', 'interest rates', 'bank failure',
  'fraud', 'scandal', 'bankruptcy', 'acquisition', 'merger',
  'valuation', 'earnings', 'investment', 'china', 'ai', 'artificial intelligence'
];

const seen = new Set();
const filtered = allItems
  .map(item => item.json)
  .filter(item => {
    const pubDate = new Date(item.pubDate || item.isoDate || 0).getTime();
    const isRecent = pubDate > fourHoursAgo || !item.pubDate;
    const title = (item.title || '').toLowerCase();
    const isRelevant = keywords.some(kw => title.includes(kw));
    const key = item.title;
    if (seen.has(key)) return false;
    seen.add(key);
    return isRecent && isRelevant;
  })
  .slice(0, 8) // Take top 8 most relevant items
  .map(item => ({
    title: item.title,
    summary: item.contentSnippet || item.summary || '',
    link: item.link,
    published: item.pubDate || item.isoDate
  }));

if (filtered.length === 0) {
  return [{ json: { skip: true, reason: 'No significant news found' } }];
}

return [{ json: { articles: filtered, count: filtered.length, skip: false } }];

// Build the context string for the AI from collected news headlines
const data = $input.first().json;
const articles = data.articles || [];

const headlines = articles
  .map((a, i) => `${i+1}. ${a.title}\n   ${a.summary ? a.summary.slice(0, 150) + '...' : '(no summary)'}\n   Published: ${a.published || 'unknown'}\n`)
  .join('\n');

return [{ json: { newsContext: headlines, articleCount: articles.length } }];

// Build the morning wisdom prompt (no news context needed)
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const today = days[new Date().getDay()];
const month = new Date().toLocaleString('en-US', { month: 'long' });

return [{ json: {
  newsContext: null,
  dayContext: `It is ${today}, ${month} ${new Date().getDate()}, ${new Date().getFullYear()}.`
} }];

